#include "dynamic_session_due.hpp"
#include "resident/domains/travel/movement_exact_detail.hpp"
#include <algorithm>
#include <set>
#include <tuple>
namespace hanmo::resident {using namespace movement_detail;namespace {
std::vector<DynamicSessionExpiryDue> all(const CommonStore& common,const MilitaryExactState& state,const DynamicMilitarySessionOriginalRead& original,const WorldMoment& current,ExactArithmeticBudget b){
 take(encode_world_moment(current,b));std::vector<DynamicSessionExpiryDue> result;
 for(const auto& row:state.session_current_states.rows()){
  const auto& session=row.second;if(row.first!=dynamic_military_session_key(session.session_ref,session.generation)||session.generation<1)fail("DynamicMilitarySessionKeyMismatch",row.first);
  const auto* initial=state.session_state_sources.find(session.initialization_source_ref.id);if(!initial||session.initialization_source_ref.domain!="military"||session.initialization_source_ref.kind!="dynamic_session_state"||!std::holds_alternative<DynamicSessionInitialized>(initial->payload)||initial->session_ref!=session.session_ref||initial->generation!=session.generation)fail("DynamicMilitarySessionInitializationRequired",row.first);
  take(original.validate_actual_session_initialization(*initial));const auto* head=common.state().facts.find(initial->id);if(!head||head->domain!="military"||head->kind!="dynamic_session_state")fail("DynamicMilitarySessionInitializationHeadRequired",row.first);
  if(take(compare_world_moments(session.opened_at,current,b))>0)fail("DynamicMilitarySessionInFuture",row.first);
  if(const auto* terminal=std::get_if<DynamicMilitaryTerminal>(&session.lifecycle)){if(take(compare_world_moments(terminal->closed_at,current,b))>0)fail("DynamicMilitaryTerminalInFuture",row.first);for(const auto& unit:session.unit_tactical_states)if(!std::holds_alternative<DynamicNoPosture>(unit.posture))fail("DynamicMilitaryTerminalPostureOpen",unit.unit_ref);if(terminal->unresolved_committed_effect_refs.empty())continue;}
  std::set<StableId> units;for(const auto& unit:session.unit_tactical_states){if(!units.insert(unit.unit_ref).second)fail("DuplicateDynamicMilitaryUnitCurrent",unit.unit_ref);
   std::set<DynamicMilitaryStatusKind> kinds;for(const auto& status:unit.statuses){if(!kinds.insert(status.kind).second||!source_valid(status.retained_activation_ref)||take(compare_world_moments(status.valid_from,status.expires_at,b))>=0||take(compare_world_moments(status.valid_from,current,b))>0||take(compare_world_moments(status.expires_at,current,b))<0)fail("DynamicMilitaryStatusGateMismatch",unit.unit_ref);take(original.validate_actual_status(session.session_ref,session.generation,unit.unit_ref,status));result.push_back({session.session_ref,session.generation,unit.unit_ref,status.expires_at,status.retained_activation_ref,DynamicStatusExpired{unit.unit_ref,status.kind,status.retained_activation_ref,status.expires_at}});}
   take(original.validate_actual_posture(session.session_ref,session.generation,unit.unit_ref,unit.posture));std::visit([&](const auto& posture){using T=std::decay_t<decltype(posture)>;if constexpr(!std::is_same_v<T,DynamicNoPosture>){const auto& source=[&]()->const SourceRef&{if constexpr(std::is_same_v<T,DynamicSupportPosture>)return posture.token.activation_ref;else return posture.activation_ref;}();const auto& from=[&]()->const WorldMoment&{if constexpr(std::is_same_v<T,DynamicSupportPosture>)return posture.token.valid_from;else return posture.valid_from;}();const auto& end=[&]()->const WorldMoment&{if constexpr(std::is_same_v<T,DynamicSupportPosture>)return posture.token.expires_at;else return posture.expires_at;}();if(!source_valid(source)||take(compare_world_moments(from,end,b))>=0||take(compare_world_moments(from,current,b))>0||take(compare_world_moments(end,current,b))<0)fail("DynamicMilitaryPostureGateMismatch",unit.unit_ref);result.push_back({session.session_ref,session.generation,unit.unit_ref,end,source,DynamicPostureClosed{unit.unit_ref,source,DynamicPostureCloseReason::expired,source,{}}});}},unit.posture);
  }
 }
 std::sort(result.begin(),result.end(),[&](const auto& a,const auto& z){const auto cmp=take(compare_world_moments(a.at,z.at,b));if(cmp)return cmp<0;auto key=[](const auto& x){Integer status=-1;if(const auto* s=std::get_if<DynamicStatusExpired>(&x.original_transition))status=Integer(s->status_kind);return std::make_tuple(x.session_ref,x.generation,x.unit_ref,x.original_transition.index(),status);};return key(a)<key(z);});return result;
}
}
Outcome<std::vector<DynamicSessionExpiryDue>> collect_dynamic_session_expiries_at(const CommonStore& c,const MilitaryExactState& state,const DynamicMilitarySessionOriginalRead& sources,const WorldMoment& current,const WorldMoment& at,ExactArithmeticBudget b){return guard<std::vector<DynamicSessionExpiryDue>>([&]{if(take(compare_world_moments(at,current,b))<0)fail("DynamicMilitaryPastExpiryQuery");auto result=all(c,state,sources,current,b);result.erase(std::remove_if(result.begin(),result.end(),[&](const auto& item){return !same_moment(item.at,at,b);}),result.end());return result;});}
Outcome<std::optional<WorldMoment>> predict_dynamic_session_expiry(const CommonStore& c,const MilitaryExactState& state,const DynamicMilitarySessionOriginalRead& sources,const WorldMoment& current,ExactArithmeticBudget b){return guard<std::optional<WorldMoment>>([&]()->std::optional<WorldMoment>{auto result=all(c,state,sources,current,b);if(result.empty())return {};return result.front().at;});}
Outcome<std::vector<MomentOwnerSource>> apply_dynamic_session_expiries_in_candidate(CommonStore& c,const MilitaryState& legacy,MilitaryExactState& state,const DynamicMilitarySessionOriginalRead& original,const CurrentMomentRead& clock,ExactArithmeticBudget b){return guard<std::vector<MomentOwnerSource>>([&]{const auto at=take(clock.read_current_moment());const auto due=take(collect_dynamic_session_expiries_at(c,state,original,at,at,b));std::vector<MomentOwnerSource> result;for(const auto& item:due){DynamicSessionTransitionPayload transition=std::visit([](const auto& value)->DynamicSessionTransitionPayload{return value;},item.original_transition);auto ref=take(apply_dynamic_military_session_transition_in_candidate(c,legacy,state,original,clock,item.session_ref,item.generation,transition,b));result.push_back({std::move(ref),2});}if(!take(collect_dynamic_session_expiries_at(c,state,original,at,at,b)).empty())fail("DynamicMilitaryExpiryClosureIncomplete");return result;});}
}
